1	import { test, before, after } from 'node:test';
2	import assert from 'node:assert/strict';
3	import { connect } from 'node:net';
4	import type { Socket } from 'node:net';
5	import { existsSync, readFileSync } from 'node:fs';
6	import { join } from 'node:path';
7	import { startServer, removeDataDir, type StartedServer } from '../testing/server.ts';
8	
9	// 请求体整份字节上限（1,000,000 字节）的端到端回归：真实起一份 server.ts，
10	// 只访问公开的 POST/GET /api/ideas。这里保护的是「整份请求体大小限制」，
11	// 与 idea-fields.ts 里标题/详细说明/使用场景按 Unicode 码点计算的字符上限是两回事，
12	// 两种限制不能混为一谈：
13	//   - 大小按实际传输的 UTF-8 字节数累计：JSON 的字段名、括号、引号、字段外空白都计入，
14	//     中文（3 字节）、表情（4 字节）不能按一个字符当作一个字节；
15	//   - 整份 JSON 合法且正文恰好 1,000,000 字节：201 且完整保存，随后可读到原样的新意见；
16	//     只多一个字节：400、error 为“请求体过大”、响应不带 idea；
17	//   - 明确 Content-Length 与不预告总长度的 Transfer-Encoding: chunked 走同一条判定，
18	//     chunked 的超限可能发生在中途，也可能直到最后一段才发生——不能因为单段较小、
19	//     或前面的字节已经像一份完整意见就接受整次提交；
20	//   - 超限后客户端继续把正文发完并保持连接等待，必须收到完整、可解析的 400，
21	//     不能只看到连接断开；正文同时有 JSON 格式问题时仍报告“请求体过大”，
22	//     未超限的非法 JSON 继续返回现有的格式错误；
23	//   - 被拒绝的请求不入库：原有意见的数量、顺序、id、createdAt 与文字逐字不变，
24	//     不新增截断记录，也不保存已经收到的前缀，磁盘上不残留 .tmp。
25	
26	const MAX_BODY_BYTES = 1_000_000;
27	
28	interface Idea {
29	  id: string;
30	  title: string;
31	  description: string;
32	  scenario: string;
33	  createdAt: string;
34	}
35	
36	// 三个字段都符合现有规则的固定内容：含中文、表情、ZWJ 表情与空白换行，
37	// 用来验证跨 TCP 段/分块边界拆字后保存仍逐字完整。
38	const FIELDS = {
39	  title: '字节边界标题 边界',
40	  description: '说明含中文：边界测试。\n第二行保留换行与空格  😀',
41	  scenario: '使用场景：中文字与表情 😮‍💨🌙 尾',
42	};
43	const points = (text: string): number => Array.from(text).length;
44	assert.ok(points(FIELDS.title) <= 120);
45	assert.ok(points(FIELDS.description) <= 5000);
46	assert.ok(points(FIELDS.scenario) <= 1000);
47	
48	let server: StartedServer;
49	
50	before(async () => {
51	  server = await startServer();
52	});
53	
54	after(async () => {
55	  await server.stop();
56	  removeDataDir(server);
57	});
58	
59	async function listIdeas(): Promise<Idea[]> {
60	  const res = await fetch(`${server.origin}/api/ideas`);
61	  assert.equal(res.status, 200);
62	  const data = await res.json();
63	  assert.ok(Array.isArray(data.ideas));
64	  return data.ideas as Idea[];
65	}
66	
67	function ideasFile(): string {
68	  return join(server.dataDir, 'ideas.json');
69	}
70	
71	function readDisk(): Buffer {
72	  return readFileSync(ideasFile());
73	}
74	
75	// 直接走原始 TCP：fetch/undici 不提供 Transfer-Encoding: chunked 的分段控制，
76	// 也无法刻意把一个多字节字符的 UTF-8 字节拆到相邻两次写入。
77	interface RawResponse {
78	  status: number;
79	  headers: Record<string, string>;
80	  rawBody: Buffer;
81	  text: string;
82	  json: any;
83	}
84	
85	interface RawOptions {
86	  // 原始正文的字节序列（不含 chunked 帧头）；按数组元素逐次写入
87	  pieces: Buffer[];
88	  chunked?: boolean;
89	  // 每次写入之间的间隔：模拟慢速客户端，验证服务不会在正文发完前提前响应或断开
90	  delayMs?: number;
91	}
92	
93	function rawPost({ pieces, chunked = false, delayMs = 2 }: RawOptions): Promise<RawResponse> {
94	  const port = Number(new URL(server.origin).port);
95	  const totalBytes = pieces.reduce((sum, piece) => sum + piece.length, 0);
96	  const headLines = [
97	    'POST /api/ideas HTTP/1.1',
98	    'Host: 127.0.0.1',
99	    'Content-Type: application/json',
100	    'Connection: close',
101	    chunked
102	      ? 'Transfer-Encoding: chunked'
103	      : `Content-Length: ${totalBytes}`,
104	  ];
105	  return new Promise<RawResponse>((resolve, reject) => {
106	    const sock: Socket = connect(port, '127.0.0.1');
107	    let received = Buffer.alloc(0);
108	    let sendingDone = false;
109	    let settled = false;
110	    const fail = (error: Error): void => {
111	      if (settled) return;
112	      settled = true;
113	      sock.destroy();
114	      reject(error);
115	    };
116	    sock.on('error', (error) => fail(error));
117	    sock.on('data', (chunk) => {
118	      // 超限请求必须先排空正文再回复：正文没发完就收到任何字节，
119	      // 说明服务提前响应（或实现退回到读完即断的旧行为）
120	      if (!sendingDone) fail(new Error('服务在请求体发送完成前就返回了数据'));
121	      received = Buffer.concat([received, chunk]);
122	    });
123	    sock.on('end', () => {
124	      if (settled) return;
125	      const split = received.indexOf('\r\n\r\n');
126	      if (split === -1) {
127	        fail(new Error('连接在收到完整响应前结束（只看到连接断开）'));
128	        return;
129	      }
130	      const headerText = received.subarray(0, split).toString('latin1');
131	      const rawBody = received.subarray(split + 4);
132	      const lines = headerText.split('\r\n');
133	      const status = Number((lines[0].match(/HTTP\/1\.1 (\d+)/) ?? [])[1]);
134	      const headers: Record<string, string> = {};
135	      for (const line of lines.slice(1)) {
136	        const at = line.indexOf(':');
137	        if (at > 0) headers[line.slice(0, at).trim().toLowerCase()] = line.slice(at + 1).trim();
138	      }
139	      // 响应必须按声明的长度完整到达，不能被截断
140	      const declared = Number(headers['content-length']);
141	      if (Number.isFinite(declared)) {
142	        assert.equal(rawBody.length, declared, '响应正文应与 content-length 等长');
143	      }
144	      const text = rawBody.toString('utf8');
145	      let json: any;
146	      try {
147	        json = JSON.parse(text);
148	      } catch {
149	        json = undefined;
150	      }
151	      settled = true;
152	      resolve({ status, headers, rawBody, text, json });
153	    });
154	    sock.on('connect', async () => {
155	      try {
156	        await write(sock, headLines.join('\r\n') + '\r\n\r\n');
157	        for (let i = 0; i < pieces.length; i++) {
158	          // 间隔只放在段与段之间：最后一段发出后服务端即可判定请求结束，
159	          // 不能在测试侧再人为拖延，否则会把正常回复误判成“正文没发完就响应”
160	          if (i > 0 && delayMs > 0) await sleep(delayMs);
161	          const piece = pieces[i];
162	          if (chunked) await write(sock, Buffer.from(`${piece.length.toString(16)}\r\n`, 'ascii'));
163	          await write(sock, piece);
164	          if (chunked) await write(sock, Buffer.from('\r\n', 'ascii'));
165	        }
166	        if (chunked) await write(sock, Buffer.from('0\r\n\r\n', 'ascii'));
167	        sendingDone = true;
168	      } catch (error) {
169	        fail(error instanceof Error ? error : new Error(String(error)));
170	      }
171	    });
172	  });
173	}
174	
175	function write(sock: Socket, data: Buffer | string): Promise<void> {
176	  return new Promise((resolve, reject) => {
177	    sock.write(data, (error) => (error ? reject(error) : resolve()));
178	  });
179	}
180	
181	function sleep(ms: number): Promise<void> {
182	  return new Promise((resolve) => setTimeout(resolve, ms));
183	}
184	
185	// 在给定字节偏移处把正文切成多段（偏移允许落在一个多字节字符的 UTF-8 序列内部）
186	function cutAt(body: Buffer, offsets: number[]): Buffer[] {
187	  const sorted = [...new Set(offsets)].filter((o) => o > 0 && o < body.length).sort((a, b) => a - b);
188	  const pieces: Buffer[] = [];
189	  let prev = 0;
190	  for (const offset of sorted) {
191	    pieces.push(body.subarray(prev, offset));
192	    prev = offset;
193	  }
194	  pieces.push(body.subarray(prev));
195	  return pieces;
196	}
197	
198	// 构造 {三个合法字段, padding:<填充>} 的整份 JSON，使其 UTF-8 字节数恰好为 target。
199	// multibyte 为 true 时填充主要用 3 字节的“中”：整份 JSON 的字符数远低于 target，
200	// 若实现误按字符计数就不会超限——用于区分“按字节”与“按字符”两种判定。
201	function paddedBody(target: number, multibyte = false): Buffer {
202	  const base = Buffer.byteLength(JSON.stringify({ ...FIELDS, padding: '' }), 'utf8');
203	  const need = target - base;
204	  assert.ok(need >= 0, `目标字节数 ${target} 小于基础 JSON 的 ${base} 字节`);
205	  let padding: string;
206	  if (!multibyte) {
207	    padding = 'x'.repeat(need);
208	  } else {
209	    const full = Math.floor(need / 3);
210	    const rest = need - full * 3;
211	    padding = '中'.repeat(full) + 'x'.repeat(rest);
212	  }
213	  const body = Buffer.from(JSON.stringify({ ...FIELDS, padding }), 'utf8');
214	  assert.equal(body.length, target);
