});
child.stderr.on('data', d => process.stderr.write('[server] ' + d));

const sleep = ms => new Promise(r => setTimeout(r, ms));
function rawSend(rawRequest, destroyAfterMs) {
  const port = Number(new URL(origin).port);
  return new Promise((resolve) => {
    const sock = connect(port, '127.0.0.1');
    let got = Buffer.alloc(0);
    let outcome = 'no-response';
    sock.on('data', d => { got = Buffer.concat([got, d]); });
    sock.on('error', () => {});
    sock.on('close', () => resolve({ outcome, got: got.toString('latin1') }));
    sock.on('connect', async () => {
      sock.write(rawRequest);
      await sleep(destroyAfterMs);
      sock.destroy();
    });
  });
}

async function run() {
  // seed one idea
  await fetch(origin + '/api/ideas', { method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({title:'原标题', description:'原说明\n换行', scenario:'场景 😀'}) });

  const full = JSON.stringify({ title: '中断标题', description: '中断说明 完整内容', scenario: '中断场景' });
  const fullBuf = Buffer.from(full, 'utf8');

  // Case 1: Content-Length declares full+10, send full prefix (itself complete parseable JSON w/ all fields), abort
  const req1 = [
    'POST /api/ideas HTTP/1.1','Host: x','Content-Type: application/json','Content-Length: ' + (fullBuf.length + 10),'Connection: close','',''
  ].join('\r\n') + full;
  const r1 = await rawSend(req1, 50);
  console.log('Case1 response prefix:', JSON.stringify(r1.got.slice(0,80)));

  // Case 2: Content-Length full, send only partial JSON (truncated mid-string), abort
  const req2head = 'POST /api/ideas HTTP/1.1\r\nHost: x\r\nContent-Length: ' + fullBuf.length + '\r\nConnection: close\r\n\r\n';
  const r2 = await rawSend(req2head + full.slice(0, 20), 50);
  console.log('Case2 response prefix:', JSON.stringify(r2.got.slice(0,80)));

  // Case 3: chunked — one full data chunk containing complete idea, then FIN w/o 0-chunk
  const chunkHead = Buffer.from(fullBuf.length.toString(16) + '\r\n','ascii');
  const req3 = Buffer.concat([
    Buffer.from('POST /api/ideas HTTP/1.1\r\nHost: x\r\nTransfer-Encoding: chunked\r\nConnection: close\r\n\r\n','ascii'),
    chunkHead, fullBuf, Buffer.from('\r\n','ascii')
  ]);
  const r3 = await rawSend(req3, 50);
  console.log('Case3 response prefix:', JSON.stringify(r3.got.slice(0,80)));

  await sleep(100);
  const res = await fetch(origin + '/api/ideas');
  const data = await res.json();
  console.log('List after aborts, count =', data.ideas.length);
  console.log('titles =', data.ideas.map(i => i.title));

  // complete valid post afterwards
  const ok = await fetch(origin + '/api/ideas', { method:'POST', headers:{'content-type':'application/json'}, body: JSON.stringify({title:'新意见', description:'新说明'}) });
  console.log('post-after status', ok.status);
  const j = await ok.json();
  const list = await (await fetch(origin + '/api/ideas')).json();
  console.log('final order:', list.ideas.map(i=>i.title));
  console.log('first id matches:', list.ideas[0].id === j.idea.id);
  child.kill('SIGTERM');
}
